window.DEMO_SOURCES = {"demo/run_demo.py": "\"\"\"Execute the bounded teaching suite and retain an immutable results batch.\n\nRun with the project virtual environment. No network access occurs during runs.\nOutputs use big-endian bit strings, matching the LaTeX note.\n\"\"\"\nimport os\nfor name in ['OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS']:\n    os.environ.setdefault(name,'4')\nfrom pathlib import Path\nfrom datetime import datetime,timezone,timedelta\nimport argparse\nimport hashlib\nimport importlib.metadata as metadata\nimport json\nimport platform\nimport time\nimport pennylane as qml\nimport numpy as np\nfrom algorithms import query,phase,search\n\nROOT=Path(__file__).resolve().parent\nPROJECT=ROOT.parent\n\ndef main():\n    parser=argparse.ArgumentParser(description='Small local PennyLane learning demonstrations')\n    parser.add_argument('--run-id',default='local-demo-001')\n    parser.add_argument('--shots',type=int,default=2048)\n    parser.add_argument('--seed',type=int,default=20261012)\n    args=parser.parse_args()\n    if not args.run_id.replace('-','').replace('_','').isalnum():raise ValueError('Invalid run id')\n    if not 128<=args.shots<=8192:raise ValueError('shots must be 128..8192 for this bounded demo')\n    destination=ROOT/'results'/args.run_id\n    if destination.exists():raise FileExistsError(f'Results batch already exists: {destination}; choose a new --run-id')\n    source_paths=[Path(__file__).resolve(),ROOT/'algorithms'/'query.py',ROOT/'algorithms'/'phase.py',ROOT/'algorithms'/'search.py']\n    source_bytes={str(p.relative_to(PROJECT)):p.read_bytes() for p in source_paths}\n    source={name:hashlib.sha256(contents).hexdigest() for name,contents in source_bytes.items()}\n    start=time.perf_counter();results=[]\n    for module in [query,phase,search]:\n        print(f'Running {module.__name__}',flush=True)\n        items=module.run(seed=args.seed,shots=args.shots)\n        for item in items:\n            if not item['validation_passed']:raise AssertionError(f\"{item['id']} validation failed\")\n            if abs(sum(item['probabilities'])-1)>1e-10:raise AssertionError('Probabilities do not normalize')\n            if sum(item['counts'].values())!=item['shots']:raise AssertionError('Sample count mismatch')\n            print(f\"  {item['id']}: {item['qubits']} wires, error={item['max_error']:.3g}\",flush=True)\n        results.extend(items)\n    ids=[x['id'] for x in results]\n    if sorted(ids)!=sorted(['deutsch','dj','bv','simon','qft','qpe','order','grover']):raise AssertionError(f'Unexpected algorithm set {ids}')\n    note_manifest=json.loads((PROJECT/'output'/'pdf'/'manifest.json').read_text(encoding='utf-8'))\n    for name,contents in source_bytes.items():\n        if (PROJECT/name).read_bytes()!=contents:raise RuntimeError(f'Computation source changed during execution: {name}')\n    record={'schema_version':1,'run_id':args.run_id,\n            'executed_at':datetime.now(timezone(timedelta(hours=8))).isoformat(),\n            'backend':'PennyLane default.qubit \u00b7 ideal CPU simulator',\n            'shots':args.shots,'seed':args.seed,'total_elapsed_seconds':time.perf_counter()-start,\n            'environment':{'python':platform.python_version(),'pennylane':qml.__version__,'numpy':np.__version__,\n                           'os':platform.system(),'threads':4},\n            'hardware':json.loads((ROOT/'hardware.json').read_text(encoding='utf-8-sig')),\n            'benchmark':json.loads((ROOT/'benchmark.json').read_text(encoding='utf-8')),\n            'note':note_manifest,'source_sha256':source,'algorithms':results,\n            'limitations':['Ideal classical state-vector simulation, not quantum hardware.',\n                           'Dense teaching operators for small order-finding examples do not demonstrate scalable modular arithmetic.',\n                           'Finite-shot counts are recorded separately from exact simulator probabilities; identical seeds do not prove cross-version determinism.']}\n    destination.mkdir(parents=True)\n    for name,contents in source_bytes.items():\n        snapshot=destination/'source'/Path(name).relative_to('demo')\n        snapshot.parent.mkdir(parents=True,exist_ok=True);snapshot.write_bytes(contents)\n    (destination/'results.json').write_text(json.dumps(record,ensure_ascii=False,indent=2,allow_nan=False),encoding='utf-8')\n    with (destination/'probabilities.csv').open('w',encoding='utf-8',newline='') as stream:\n        import csv\n        writer=csv.writer(stream);writer.writerow(['algorithm','basis','exact_probability','theory_probability','sample_count','shots'])\n        for item in results:\n            for label,p,e in zip(item['labels'],item['probabilities'],item['expected_probabilities']):\n                writer.writerow([item['id'],label,p,e,item['counts'].get(label,0),item['shots']])\n    print(f'Retained results batch: {destination}',flush=True)\n\nif __name__=='__main__':main()\n", "demo/algorithms/query.py": "\"\"\"Query algorithms from note sections 1.2--1.5, run on PennyLane CPU.\n\nWire 0 is the most significant input bit. Input wires precede work wires.\nAnalytic probabilities and genuine finite-shot samples are separate runs;\nthe 1e-10 validation threshold applies to analytic probabilities, not to\nthe statistical difference between sample frequencies and probabilities.\nNo circuit here prepares a known answer as its output state.\n\"\"\"\n\nfrom collections import Counter\nfrom collections.abc import Callable\nfrom time import perf_counter\n\nimport numpy as np\nimport pennylane as qml\n\n\nPROBABILITY_TOLERANCE = 1e-10\n\n\ndef _bits(value: int, width: int) -> list[int]:\n    \"\"\"Return most-significant-bit-first binary digits, length ``width``.\"\"\"\n    return [int(bit) for bit in format(value, f\"0{width}b\")]\n\n\ndef _labels(n: int) -> list[str]:\n    return [format(value, f\"0{n}b\") for value in range(1 << n)]\n\n\ndef _point_distribution(value: int, n: int) -> list[float]:\n    return [float(index == value) for index in range(1 << n)]\n\n\ndef _evaluate(\n    body: Callable[[], None],\n    n: int,\n    qubits: int,\n    expected: list[float],\n    seed: int,\n    shots: int,\n) -> tuple[dict, np.ndarray]:\n    \"\"\"Execute a unitary body, measuring its first n wires in big-endian order.\n\n    Returns a JSON-safe analytic/sample record and raw samples of shape\n    (shots, n). Every count comes from qml.sample, never synthetic sampling.\n    \"\"\"\n    started = perf_counter()\n    analytic_device = qml.device(\"default.qubit\", wires=qubits, seed=seed)\n    sampling_device = qml.device(\"default.qubit\", wires=qubits, seed=seed)\n\n    @qml.qnode(analytic_device, interface=None, diff_method=None)\n    def analytic():\n        body()\n        return qml.probs(wires=list(range(n)))\n\n    @qml.qnode(sampling_device, interface=None, diff_method=None)\n    def sampling():\n        body()\n        return qml.sample(wires=list(range(n)))\n\n    probabilities = np.asarray(analytic(), dtype=float)\n    samples = np.asarray(qml.set_shots(sampling, shots=shots)(), dtype=int)\n    if samples.shape != (shots, n):\n        raise RuntimeError(f\"Unexpected sample shape {samples.shape}; wanted {(shots, n)}\")\n    labels = _labels(n)\n    counts = dict(sorted(Counter(\"\".join(map(str, row)) for row in samples).items()))\n    theory = np.asarray(expected, dtype=float)\n    if theory.shape != probabilities.shape:\n        raise ValueError(\"Expected probabilities and measured register have different sizes\")\n    max_error = float(np.max(np.abs(probabilities - theory)))\n    normalized = bool(abs(float(probabilities.sum()) - 1.0) <= PROBABILITY_TOLERANCE)\n    support_valid = all(probabilities[int(label, 2)] > PROBABILITY_TOLERANCE for label in counts)\n    passed = normalized and max_error <= PROBABILITY_TOLERANCE and support_valid\n    if not passed:\n        raise AssertionError(\n            f\"Quantum probability validation failed: error={max_error}, \"\n            f\"normalized={normalized}, sample_support={support_valid}\"\n        )\n    frequencies = np.array([counts.get(label, 0) / shots for label in labels])\n    record = {\n        \"qubits\": qubits,\n        \"elapsed_seconds\": float(perf_counter() - started),\n        \"labels\": labels,\n        \"probabilities\": probabilities.tolist(),\n        \"expected_probabilities\": theory.tolist(),\n        \"counts\": counts,\n        \"shots\": shots,\n        \"seed\": seed,\n        \"max_error\": max_error,\n        \"validation_passed\": bool(passed),\n        \"circuit_text\": qml.draw(analytic, decimals=2)(),\n        \"details\": {\n            \"device\": \"default.qubit\",\n            \"execution\": \"CPU statevector simulation\",\n            \"wire_order\": \"\u8f93\u5165\u6700\u9ad8\u6709\u6548\u4f4d\u5728wire 0\uff1b\u5de5\u4f5c\u5bc4\u5b58\u5668\u968f\u540e\",\n            \"probability_tolerance\": PROBABILITY_TOLERANCE,\n            \"sample_support_valid\": bool(support_valid),\n            \"empirical_max_error\": float(np.max(np.abs(frequencies - theory))),\n            \"validation_scope\": \"\u89e3\u6790\u6982\u7387\u4e0e\u72ec\u7acb\u7406\u8bba\u6bd4\u8f83\uff1b\u6709\u9650shots\u7684\u9891\u7387\u504f\u5dee\u53e6\u884c\u8bb0\u5f55\",\n        },\n    }\n    return record, samples\n\n\ndef _make_result(\n    record: dict,\n    algorithm_id: str,\n    title: str,\n    note_ref: str,\n    source_pages: str,\n    summary: str,\n    parameters: dict,\n    circuit_steps: list[str],\n) -> dict:\n    return {\n        \"id\": algorithm_id,\n        \"title\": title,\n        \"note_ref\": note_ref,\n        \"source_pages\": source_pages,\n        \"summary\": summary,\n        \"parameters\": parameters,\n        **record,\n        \"details\": dict(record[\"details\"]),\n        \"circuit_steps\": circuit_steps,\n    }\n\n\ndef _deutsch_body(values: tuple[int, int]) -> Callable[[], None]:\n    def body():\n        qml.PauliX(wires=1)\n        qml.Hadamard(wires=0)\n        qml.Hadamard(wires=1)\n        # f(x) = f(0) XOR ((f(0) XOR f(1)) AND x).\n        if values[0]:\n            qml.PauliX(wires=1)\n        if values[0] ^ values[1]:\n            qml.CNOT(wires=[0, 1])\n        qml.Hadamard(wires=0)\n\n    return body\n\n\ndef _linear_phase_body(secret: str, offset: int = 0) -> Callable[[], None]:\n    \"\"\"Deutsch--Jozsa/BV with XOR oracle f(x)=secret dot x XOR offset.\"\"\"\n    n = len(secret)\n\n    def body():\n        qml.PauliX(wires=n)\n        for wire in range(n + 1):\n            qml.Hadamard(wires=wire)\n        if offset:\n            qml.PauliX(wires=n)\n        for wire, coefficient in enumerate(secret):\n            if coefficient == \"1\":\n                qml.CNOT(wires=[wire, n])\n        for wire in range(n):\n            qml.Hadamard(wires=wire)\n\n    return body\n\n\ndef _dj_theory(secret: str, offset: int) -> list[float]:\n    \"\"\"Compute the note's Fourier character sum from a classical truth table.\n\n    This deliberately does not use a QNode or its final statevector.\n    \"\"\"\n    n = len(secret)\n    N = 1 << n\n    mask = int(secret, 2)\n    values = [((mask & x).bit_count() % 2) ^ offset for x in range(N)]\n    return [\n        (sum((-1) ** (values[x] + (x & z).bit_count()) for x in range(N)) / N) ** 2\n        for z in range(N)\n    ]\n\n\ndef _simon_matrix(secret: str) -> list[list[int]]:\n    \"\"\"Construct A over GF(2), with kernel span{secret}, or identity for zero.\n\n    For the first nonzero bit p, f_p(x)=0 and f_j(x)=x_j XOR s_j*x_p\n    for j != p. Then A has rank n-1 and exactly the promised pair collisions.\n    Its XOR oracle is a reversible CNOT network on n input + n output wires.\n    \"\"\"\n    n = len(secret)\n    matrix = [[int(row == col) for col in range(n)] for row in range(n)]\n    if \"1\" not in secret:\n        return matrix\n    pivot = secret.index(\"1\")\n    matrix[pivot] = [0] * n\n    for row, bit in enumerate(secret):\n        if row != pivot:\n            matrix[row][pivot] = int(bit)\n    return matrix\n\n\ndef _simon_body(matrix: list[list[int]]) -> Callable[[], None]:\n    n = len(matrix)\n\n    def body():\n        for wire in range(n):\n            qml.Hadamard(wires=wire)\n        for output, row in enumerate(matrix):\n            for input_wire, coefficient in enumerate(row):\n                if coefficient:\n                    qml.CNOT(wires=[input_wire, n + output])\n        for wire in range(n):\n            qml.Hadamard(wires=wire)\n\n    return body\n\n\ndef _classical_linear_value(matrix: list[list[int]], x: str) -> str:\n    bits = [int(bit) for bit in x]\n    return \"\".join(str(sum(a * b for a, b in zip(row, bits)) % 2) for row in matrix)\n\n\ndef _gf2_nullspace(rows: list[list[int]], n: int) -> tuple[int, list[list[int]]]:\n    \"\"\"RREF and a kernel basis over GF(2); never use floating-point SVD.\"\"\"\n    matrix = [row.copy() for row in rows]\n    pivot_columns = []\n    for column in range(n):\n        pivot = next(\n            (row for row in range(len(pivot_columns), len(matrix)) if matrix[row][column]),\n            None,\n        )\n        if pivot is None:\n            continue\n        pivot_row = len(pivot_columns)\n        matrix[pivot_row], matrix[pivot] = matrix[pivot], matrix[pivot_row]\n        for row in range(len(matrix)):\n            if row != pivot_row and matrix[row][column]:\n                matrix[row] = [a ^ b for a, b in zip(matrix[row], matrix[pivot_row])]\n        pivot_columns.append(column)\n    basis = []\n    for free_column in range(n):\n        if free_column in pivot_columns:\n            continue\n        vector = [0] * n\n        vector[free_column] = 1\n        for row, pivot_column in enumerate(pivot_columns):\n            vector[pivot_column] = matrix[row][free_column]\n        basis.append(vector)\n    return len(pivot_columns), basis\n\n\ndef _recover_simon(samples: np.ndarray, matrix: list[list[int]]) -> dict:\n    \"\"\"Recover from actual samples and oracle comparison, without the secret.\n\n    Rank n-1 leaves one nonzero candidate t. f(0)=f(t) verifies a nonzero\n    period. If unequal, the promise and the unique candidate imply s=0.\n    Thus the injective case may also stop at rank n-1 after two value queries.\n    \"\"\"\n    n = samples.shape[1]\n    rows: list[list[int]] = []\n    rank = 0\n    basis: list[list[int]] = []\n    for sample in samples:\n        rows.append(sample.tolist())\n        rank, basis = _gf2_nullspace(rows, n)\n        if rank == n:\n            return {\n                \"rows\": rows,\n                \"rank\": rank,\n                \"kernel_basis\": [],\n                \"recovered_s\": \"0\" * n,\n                \"verification\": {\"method\": \"\u6ee1\u79e9\u6838\u4ec5\u542b\u96f6\u5411\u91cf\", \"additional_value_queries\": 0},\n            }\n        if rank == n - 1:\n            candidate = \"\".join(map(str, basis[0]))\n            f_zero = _classical_linear_value(matrix, \"0\" * n)\n            f_candidate = _classical_linear_value(matrix, candidate)\n            accepted = f_zero == f_candidate\n            return {\n                \"rows\": rows,\n                \"rank\": rank,\n                \"kernel_basis\": [candidate],\n                \"recovered_s\": candidate if accepted else \"0\" * n,\n                \"verification\": {\n                    \"method\": \"\u5728\u552f\u4e00\u975e\u96f6\u6838\u5019\u9009\u4e0a\u6bd4\u8f83f(0)\u4e0ef(t)\uff0c\u4f9dSimon\u627f\u8bfa\u5224\u5b9a\",\n                    \"candidate\": candidate,\n                    \"f_zero\": f_zero,\n                    \"f_candidate\": f_candidate,\n                    \"candidate_accepted\": accepted,\n                    \"additional_value_queries\": 2,\n                },\n            }\n    return {\n        \"rows\": rows,\n        \"rank\": rank,\n        \"kernel_basis\": [\"\".join(map(str, vector)) for vector in basis],\n        \"recovered_s\": None,\n        \"verification\": {\"method\": \"\u771f\u5b9e\u6837\u672c\u79e9\u4e0d\u8db3\uff0c\u672a\u6062\u590d\", \"additional_value_queries\": 0},\n    }\n\n\ndef _run_deutsch(seed: int, shots: int) -> dict:\n    cases = []\n    primary = None\n    total_seconds = 0.0\n    for values in ((0, 0), (0, 1), (1, 0), (1, 1)):\n        parity = values[0] ^ values[1]\n        record, _ = _evaluate(_deutsch_body(values), 1, 2, _point_distribution(parity, 1), seed, shots)\n        total_seconds += record[\"elapsed_seconds\"]\n        case = {\"case\": \"\".join(map(str, values)), \"function_values\": list(values), \"type\": \"\u5e73\u8861\" if parity else \"\u5e38\u6570\", **record}\n        cases.append(case)\n        if values == (0, 1):\n            primary = record\n    result = _make_result(\n        primary, \"deutsch\", \"Deutsch\uff1a\u4e00\u6b21\u67e5\u8be2\u5224\u5b9a\u4e24\u70b9\u5947\u5076\", \"1.2\", \"6\u20139\",\n        \"\u5b9e\u9645\u6267\u884c\u5168\u90e84\u79cd\u4e00\u6bd4\u7279\u51fd\u6570\uff1b\u4e3b\u56fe\u4e3af(x)=x\uff0c\u6700\u7ec8\u8f93\u51fa1\u5224\u5b9a\u5e73\u8861\u3002\u89e3\u6790\u7ed3\u679c\u7cbe\u786e\uff0ccounts\u6765\u81ea\u6709\u9650shots\u6d4b\u91cf\u3002\",\n        {\"n\": 1, \"function_values\": [0, 1], \"oracle_queries_per_shot\": 1, \"cases_executed\": 4},\n        [\"\u8f85\u52a9\u4f4d\u7531X\u3001H\u51c6\u5907\u4e3a|\u2212\u27e9\", \"\u8f93\u5165\u4f4d\u65bd\u52a0H\", \"\u4ee5X/CNOT\u5b9e\u73b0\u4e00\u6b21\u5f02\u6216\u67e5\u8be2\", \"\u8f93\u5165\u4f4d\u518d\u6b21H\u5e76\u6d4b\u91cf\"],\n    )\n    result[\"elapsed_seconds\"] = total_seconds\n    result[\"details\"][\"cases\"] = cases\n    return result\n\n\ndef _run_dj(seed: int, shots: int) -> dict:\n    n = 4\n    cases = []\n    primary = None\n    total_seconds = 0.0\n    for case_name, secret, offset in ((\"constant_one\", \"0000\", 1), (\"balanced_affine\", \"1011\", 1)):\n        record, _ = _evaluate(_linear_phase_body(secret, offset), n, n + 1, _dj_theory(secret, offset), seed, shots)\n        total_seconds += record[\"elapsed_seconds\"]\n        cases.append({\"case\": case_name, \"linear_coefficient\": secret, \"offset\": offset, **record})\n        if case_name == \"balanced_affine\":\n            primary = record\n    result = _make_result(\n        primary, \"dj\", \"Deutsch\u2013Jozsa\uff1a\u5e38\u6570\u4e0e\u5e73\u8861\u51fd\u6570\", \"1.3\", \"9\u201311\",\n        \"n=4\uff0c\u8fd0\u884c\u5e381\u51fd\u6570\u4e0e\u5e73\u8861\u4eff\u5c04\u51fd\u65701011\u00b7x\u22951\u3002\u4e3b\u4f8b\u8f93\u51fa1011\uff0c\u56e0\u6b64\u4e0d\u662f\u5168\u96f6\uff1b\u5e38\u6570\u5bf9\u7167\u5fc5\u5f970000\u3002\",\n        {\"n\": n, \"linear_coefficient\": \"1011\", \"offset\": 1, \"oracle_definition\": \"f(x)=1011\u00b7x XOR 1\", \"oracle_queries_per_shot\": 1, \"cases_executed\": 2},\n        [\"4\u4e2a\u8f93\u5165\u4f4d\u65bd\u52a0H\uff0c\u8f85\u52a9\u4f4d\u51c6\u5907|\u2212\u27e9\", \"X\u4e0e3\u4e2aCNOT\u5b9e\u73b0\u4eff\u5c04\u51fd\u6570\u67e5\u8be2\", \"\u8f93\u5165\u5bc4\u5b58\u5668\u518d\u6b21\u65bd\u52a0H\", \"\u6d4b\u91cf\u5e76\u68c0\u67e5\u662f\u5426\u5168\u96f6\"],\n    )\n    result[\"elapsed_seconds\"] = total_seconds\n    result[\"details\"][\"cases\"] = cases\n    return result\n\n\ndef _run_bv(seed: int, shots: int) -> dict:\n    secret = \"101101\"\n    n = len(secret)\n    record, _ = _evaluate(_linear_phase_body(secret), n, n + 1, _point_distribution(int(secret, 2), n), seed, shots)\n    result = _make_result(\n        record, \"bv\", \"Bernstein\u2013Vazirani\uff1a\u6062\u590d\u9690\u85cf\u7ebf\u6027\u4e32\", \"1.4\", \"12\u201313\",\n        \"n=6\uff0c\u9690\u85cf\u4e32101101\u3002\u7531CNOT\u7f51\u7edc\u8ba1\u7b97\u7ebf\u6027\u51fd\u6570\uff0c\u6d4b\u91cf\u5fc5\u5f97101101\uff1b\u6bcf\u6b21\u7535\u8def\u8c03\u7528\u4e00\u6b21oracle\u3002\",\n        {\"n\": n, \"secret\": secret, \"oracle_definition\": \"f(x)=101101\u00b7x\", \"oracle_queries_per_shot\": 1},\n        [\"6\u4f4d\u5747\u5300\u53e0\u52a0\uff0c\u8f85\u52a9\u4f4d\u51c6\u5907|\u2212\u27e9\", \"\u5728\u9690\u85cf\u4e32\u4e3a1\u76844\u4e2a\u4f4d\u4e0a\u4f7f\u7528CNOT\", \"\u6700\u540eH\u5c42\u8ba9\u5b57\u7b26\u5e72\u6d89\u96c6\u4e2d\u5230\u9690\u85cf\u4e32\", \"\u6d4b\u91cf\u8f93\u51656\u4f4d\"],\n    )\n    result[\"details\"][\"recovered_s\"] = result[\"labels\"][int(np.argmax(result[\"probabilities\"]))]\n    return result\n\n\ndef _run_simon(seed: int, shots: int) -> dict:\n    n = 4\n    cases = []\n    primary = None\n    total_seconds = 0.0\n    for secret in (\"1011\", \"0000\"):\n        matrix = _simon_matrix(secret)\n        mask = int(secret, 2)\n        # Independent formula: all y for injective f; otherwise y dot s = 0.\n        expected = [\n            1 / (1 << n) if mask == 0 else (2 / (1 << n) if (mask & y).bit_count() % 2 == 0 else 0.0)\n            for y in range(1 << n)\n        ]\n        record, samples = _evaluate(_simon_body(matrix), n, 2 * n, expected, seed, shots)\n        recovery_started = perf_counter()\n        recovery = _recover_simon(samples, matrix)\n        record[\"elapsed_seconds\"] += float(perf_counter() - recovery_started)\n        total_seconds += record[\"elapsed_seconds\"]\n        recovery_ok = recovery[\"recovered_s\"] == secret\n        if not recovery_ok:\n            raise AssertionError(f\"Simon sample recovery failed for {secret}: {recovery}\")\n        # Exhaustive classical promise check, separate from probability prediction.\n        truth_table = {x: _classical_linear_value(matrix, x) for x in _labels(n)}\n        promise_valid = all(\n            (truth_table[x] == truth_table[z]) == (x == z or (int(x, 2) ^ int(z, 2)) == mask)\n            for x in truth_table for z in truth_table\n        )\n        if not promise_valid:\n            raise AssertionError(\"Constructed Simon oracle violates its classical promise\")\n        record[\"details\"].update({\n            \"oracle_matrix_gf2\": matrix,\n            \"oracle_truth_table\": truth_table,\n            \"promise_validated\": promise_valid,\n            \"sample_rows\": samples[: min(shots, 16)].tolist(),\n            \"sample_rows_shown\": min(shots, 16),\n            \"sample_rows_total\": shots,\n            \"recovery_rows\": recovery[\"rows\"],\n            \"recovery_samples_used\": len(recovery[\"rows\"]),\n            \"rank\": recovery[\"rank\"],\n            \"kernel_basis\": recovery[\"kernel_basis\"],\n            \"recovered_s\": recovery[\"recovered_s\"],\n            \"candidate_verification\": recovery[\"verification\"],\n            \"recovery_validated\": bool(recovery_ok),\n            \"orthogonality_violations\": int(sum((int(\"\".join(map(str, row)), 2) & mask).bit_count() % 2 for row in samples)),\n        })\n        case = {\"case\": \"two_to_one\" if mask else \"injective\", \"secret\": secret, **record}\n        cases.append(case)\n        if mask:\n            primary = record\n    result = _make_result(\n        primary, \"simon\", \"Simon\uff1a\u91c7\u6837\u6b63\u4ea4\u7ea6\u675f\u5e76\u89e3\u7ebf\u6027\u65b9\u7a0b\", \"1.5\", \"13\u201317\",\n        \"8\u91cf\u5b50\u6bd4\u7279\u5b9e\u73b04\u8f93\u5165+4\u8f93\u51fa\u3002\u4e3b\u4f8b\u7531\u771f\u5b9e\u91c7\u6837\u6062\u590d1011\uff0c\u6240\u6709\u6837\u672c\u6ee1\u8db3y\u00b71011=0\uff1b\u53e6\u8fd0\u884c\u4e00\u4e00\u51fd\u6570\u5bf9\u7167\u3002\",\n        {\"n\": n, \"m\": n, \"secret\": \"1011\", \"oracle_definition\": \"f(x)=Ax over GF(2), rank(A)=3, kernel(A)=span{1011}\", \"oracle_queries_per_shot\": 1, \"cases_executed\": 2},\n        [\"4\u8f93\u5165\u4f4dH\uff0c4\u8f93\u51fa\u4f4d\u4fdd\u6301|0000\u27e9\", \"\u7528CNOT\u7f51\u7edc\u6267\u884c|x\u27e9|z\u27e9\u2192|x\u27e9|z\u2295Ax\u27e9\", \"\u8f93\u5165\u4f4dH\u540e\u5b9e\u9645\u91c7\u6837\", \"GF(2)\u6d88\u5143\u5e76\u901a\u8fc7f(0)=f(t)\u9a8c\u8bc1\u552f\u4e00\u975e\u96f6\u6838\u5019\u9009\"],\n    )\n    result[\"elapsed_seconds\"] = total_seconds\n    # Copy before assigning cases: avoid recursive dictionaries in JSON output.\n    result[\"details\"] = {**primary[\"details\"], \"cases\": cases}\n    return result\n\n\ndef run(seed: int = 20261012, shots: int = 2048) -> list[dict]:\n    \"\"\"Run four query-algorithm demonstrations with a bounded local budget.\n\n    The nine case circuits use at most eight simulated qubits. ``shots`` is\n    the finite sample count per case, not an analytic precision parameter.\n    A recovery failure is raised explicitly rather than hidden by fake counts.\n    \"\"\"\n    if not isinstance(seed, int) or isinstance(seed, bool) or seed < 0:\n        raise ValueError(\"seed must be a nonnegative integer\")\n    if not isinstance(shots, int) or isinstance(shots, bool) or shots < 16:\n        raise ValueError(\"shots must be an integer >= 16 for the Simon recovery demonstration\")\n    return [_run_deutsch(seed, shots), _run_dj(seed, shots), _run_bv(seed, shots), _run_simon(seed, shots)]\n", "demo/algorithms/phase.py": "\"\"\"Small PennyLane QFT, QPE, and order-finding demonstrations.\n\nAll registers use big-endian wire order.  F_N has the positive exponent\nexp(2 pi i x y / N); phase estimation therefore applies its adjoint.\nAnalytic probabilities are compared with independent finite Fourier sums.\nFinite-shot counts are produced by PennyLane sample/set_shots, never by a\nseparate NumPy sampling routine.  The order oracle is a small dense matrix,\nnot a scalable implementation of reversible modular arithmetic.\n\"\"\"\n\nfrom collections import Counter\nfrom fractions import Fraction\nfrom math import gcd, lcm\nfrom time import perf_counter\n\nimport numpy as np\nimport pennylane as qml\n\n\nTOLERANCE = 1e-10\n\n\ndef _labels(wires: int) -> list[str]:\n    return [format(index, f\"0{wires}b\") for index in range(2**wires)]\n\n\ndef _basis_bits(value: int, wires: int) -> np.ndarray:\n    return np.array([int(bit) for bit in format(value, f\"0{wires}b\")], dtype=int)\n\n\ndef _qft(wires: list[int]) -> None:\n    \"\"\"Apply positive-phase QFT, including output bit reversal.\n\n    wires[0] is the most significant bit.  The ControlledPhaseShift matrix\n    is diag(1, 1, 1, exp(i alpha)); exchanging its two wires is immaterial.\n    \"\"\"\n    for index, target in enumerate(wires):\n        qml.Hadamard(wires=target)\n        for other_index in range(index + 1, len(wires)):\n            angle = 2 * np.pi / 2 ** (other_index - index + 1)\n            qml.ControlledPhaseShift(angle, wires=[wires[other_index], target])\n    for index in range(len(wires) // 2):\n        qml.SWAP(wires=[wires[index], wires[-index - 1]])\n\n\ndef _fourier_probabilities(phase: float, estimation_bits: int) -> np.ndarray:\n    \"\"\"Independent QPE distribution from finite phase-wave sums.\n\n    Returns length 2**estimation_bits, with integer y in big-endian order.\n    It avoids division by sin(pi*delta), so exact phases have no 0/0 case.\n    \"\"\"\n    size = 2**estimation_bits\n    x = np.arange(size, dtype=float)\n    y = np.arange(size, dtype=float)\n    amplitudes = np.exp(2j * np.pi * x[:, None] * (phase - y[None, :] / size)).mean(axis=0)\n    return np.abs(amplitudes) ** 2\n\n\ndef _sample_counts(sample_qnode, shots: int, wire_count: int) -> dict[str, int]:\n    sample = np.asarray(qml.set_shots(sample_qnode, shots=shots)(), dtype=int)\n    sample = sample.reshape(shots, wire_count)\n    observed = Counter(\"\".join(str(int(bit)) for bit in row) for row in sample)\n    return {label: int(observed.get(label, 0)) for label in _labels(wire_count)}\n\n\ndef _complex_data(state: np.ndarray, labels: list[str]) -> list[dict]:\n    return [\n        {\n            \"label\": label,\n            \"real\": float(np.real(amplitude)),\n            \"imag\": float(np.imag(amplitude)),\n            \"phase_radians\": float(np.angle(amplitude)),\n        }\n        for label, amplitude in zip(labels, state)\n    ]\n\n\ndef _draw(circuit, wire_count: int) -> str:\n    return qml.draw(circuit, decimals=3, wire_order=list(range(wire_count)), show_matrices=False)()\n\n\ndef _qft_demo(seed: int, shots: int) -> dict:\n    started = perf_counter()\n    wires = [0, 1, 2]\n    x = 5\n    device = qml.device(\"default.qubit\", wires=3, seed=seed)\n\n    def prepare():\n        qml.BasisState(_basis_bits(x, 3), wires=wires)\n        _qft(wires)\n\n    @qml.qnode(device)\n    def state_circuit():\n        prepare()\n        return qml.state()\n\n    @qml.qnode(device)\n    def sample_circuit():\n        prepare()\n        return qml.sample(wires=wires)\n\n    @qml.qnode(device)\n    def roundtrip_circuit():\n        prepare()\n        qml.adjoint(_qft)(wires)\n        return qml.state()\n\n    state = np.asarray(state_circuit(), dtype=complex)\n    probabilities = np.abs(state) ** 2\n    expected_state = np.exp(2j * np.pi * x * np.arange(8) / 8) / np.sqrt(8)\n    expected_probabilities = np.full(8, 1 / 8, dtype=float)\n    roundtrip = np.asarray(roundtrip_circuit(), dtype=complex)\n    expected_input = np.eye(1, 8, x, dtype=complex).ravel()\n    amplitude_error = float(np.max(np.abs(state - expected_state)))\n    probability_error = float(np.max(np.abs(probabilities - expected_probabilities)))\n    roundtrip_error = float(np.max(np.abs(roundtrip - expected_input)))\n    max_error = max(amplitude_error, probability_error, roundtrip_error)\n    counts = _sample_counts(sample_circuit, shots, 3)\n    labels = _labels(3)\n    return {\n        \"id\": \"qft\",\n        \"title\": \"\u91cf\u5b50\u5085\u91cc\u53f6\u53d8\u6362\uff1a\u5747\u5300\u6982\u7387\u4e2d\u7684\u76f8\u4f4d\u7ed3\u6784\",\n        \"note_ref\": \"3.4\",\n        \"source_pages\": [32, 33, 34, 35],\n        \"summary\": \"\u5bf9 |101\u27e9\uff08x=5\uff09\u6267\u884c\u6b63\u76f8\u4f4d F\u2088\u3002\u516b\u79cd\u6d4b\u91cf\u7ed3\u679c\u7b49\u6982\u7387\uff0c\u4f46\u590d\u632f\u5e45\u542b e^{2\u03c0i\u00b75y/8} \u7684\u76f8\u4f4d\uff1b\u9006\u53d8\u6362\u6062\u590d\u539f\u8f93\u5165\u3002\",\n        \"parameters\": {\"input_integer\": x, \"input_bits\": \"101\", \"estimation_bits\": 3, \"fourier_sign\": \"+\", \"inverse_roundtrip\": True},\n        \"qubits\": 3,\n        \"elapsed_seconds\": float(perf_counter() - started),\n        \"labels\": labels,\n        \"probabilities\": probabilities.tolist(),\n        \"expected_probabilities\": expected_probabilities.tolist(),\n        \"counts\": counts,\n        \"shots\": shots,\n        \"seed\": seed,\n        \"max_error\": max_error,\n        \"validation_passed\": bool(max_error < TOLERANCE and sum(counts.values()) == shots),\n        \"circuit_text\": _draw(state_circuit, 3),\n        \"circuit_steps\": [\"\u5236\u5907\u6700\u9ad8\u4f4d\u5728\u4e0a\u7684 |101\u27e9\", \"\u9010\u7ebf\u6267\u884c H \u4e0e\u6b63\u89d2\u53d7\u63a7\u76f8\u4f4d\u95e8\", \"\u4ea4\u6362\u7b2c1\u30013\u7ebf\uff0c\u5f97\u5230\u6807\u51c6\u4f4d\u5e8f\u7684 F\u2088\", \"\u53e6\u6267\u884c F\u2088\u2020\uff0c\u68c0\u9a8c\u8f93\u5165\u6062\u590d\"],\n        \"details\": {\n            \"amplitudes\": _complex_data(state, labels),\n            \"expected_amplitudes\": _complex_data(expected_state, labels),\n            \"qft_input\": \"101\",\n            \"out_error\": roundtrip_error,\n            \"roundtrip_amplitudes\": _complex_data(roundtrip, labels),\n            \"amplitude_error\": amplitude_error,\n            \"probability_error\": probability_error,\n            \"roundtrip_error\": roundtrip_error,\n            \"validation_tolerance\": TOLERANCE,\n            \"display_explanation\": \"\u6982\u7387\u67f1\u72b6\u56fe\u4e3a\u5747\u5300\u5206\u5e03\uff0c\u5e76\u4e0d\u8868\u793aQFT\u6ca1\u6709\u4f5c\u7528\uff1b\u8bf7\u540c\u65f6\u5c55\u793a\u5b9e\u90e8\u3001\u865a\u90e8\u6216\u76f8\u4f4d\u3002\u8fd9\u91cc\u7684\u590d\u632f\u5e45\u6765\u81eaPennyLane\u72b6\u6001\u5411\u91cf\uff0ccounts\u6765\u81ea\u771f\u5b9e\u7684\u6a21\u62df\u5668\u6709\u9650\u6b21\u6d4b\u91cf\u3002\",\n            \"device\": \"default.qubit CPU state-vector simulator\",\n        },\n    }\n\n\ndef _phase_estimation_case(phase: float, m: int, seed: int, shots: int) -> dict:\n    started = perf_counter()\n    controls = list(range(m))\n    target = m\n    device = qml.device(\"default.qubit\", wires=m + 1, seed=seed)\n\n    def prepare():\n        qml.PauliX(wires=target)\n        for wire in controls:\n            qml.Hadamard(wires=wire)\n        for index, wire in enumerate(controls):\n            power = 2 ** (m - index - 1)\n            qml.ControlledPhaseShift(2 * np.pi * phase * power, wires=[wire, target])\n        qml.adjoint(_qft)(controls)\n\n    @qml.qnode(device)\n    def probabilities_circuit():\n        prepare()\n        return qml.probs(wires=controls)\n\n    @qml.qnode(device)\n    def sample_circuit():\n        prepare()\n        return qml.sample(wires=controls)\n\n    probabilities = np.asarray(probabilities_circuit(), dtype=float)\n    expected = _fourier_probabilities(phase, m)\n    max_error = float(np.max(np.abs(probabilities - expected)))\n    counts = _sample_counts(sample_circuit, shots, m)\n    nearest_y = int(np.floor(2**m * phase + 0.5)) % 2**m\n    estimate = nearest_y / 2**m\n    phase_distance = min(abs(phase - estimate), 1 - abs(phase - estimate))\n    exact = bool(abs(2**m * phase - round(2**m * phase)) < TOLERANCE)\n    return {\n        \"phase\": float(phase),\n        \"phase_fraction\": str(Fraction(phase).limit_denominator(1000)),\n        \"estimation_bits\": m,\n        \"qubits\": m + 1,\n        \"elapsed_seconds\": float(perf_counter() - started),\n        \"exact_grid_phase\": exact,\n        \"labels\": _labels(m),\n        \"probabilities\": probabilities.tolist(),\n        \"expected_probabilities\": expected.tolist(),\n        \"counts\": counts,\n        \"shots\": shots,\n        \"seed\": seed,\n        \"max_error\": max_error,\n        \"validation_passed\": bool(max_error < TOLERANCE and abs(probabilities.sum() - 1) < TOLERANCE and sum(counts.values()) == shots),\n        \"nearest_integer\": nearest_y,\n        \"nearest_bits\": format(nearest_y, f\"0{m}b\"),\n        \"nearest_phase_estimate\": float(estimate),\n        \"circular_phase_error\": float(phase_distance),\n        \"nearest_probability\": float(probabilities[nearest_y]),\n        \"nearest_probability_lower_bound\": float(4 / np.pi**2),\n        \"circuit_text\": _draw(probabilities_circuit, m + 1),\n    }\n\n\ndef _qpe_demo(seed: int, shots: int) -> dict:\n    started = perf_counter()\n    exact = _phase_estimation_case(5 / 16, 4, seed + 101, shots)\n    approximate = _phase_estimation_case(1 / 3, 6, seed + 102, shots)\n    return {\n        \"id\": \"qpe\",\n        \"title\": \"\u76f8\u4f4d\u4f30\u8ba1\uff1a\u7cbe\u786e\u4e8c\u8fdb\u5236\u76f8\u4f4d\u4e0e\u975e\u6574\u683c\u76f8\u4f4d\",\n        \"note_ref\": \"3.5\",\n        \"source_pages\": [36, 37],\n        \"summary\": \"\u76f8\u4f4d5/16\u75284\u4e2a\u8f85\u52a9\u6bd4\u7279\u5fc5\u5f970101\uff1b\u76f8\u4f4d1/3\u75286\u4e2a\u8f85\u52a9\u6bd4\u7279\u5f62\u6210\u5c16\u5cf0\u5206\u5e03\uff0c\u6700\u63a5\u8fd1\u7684\u7ed3\u679c\u662f010101\uff0821/64\uff09\uff0c\u5e76\u975e\u6bcf\u6b21\u6d4b\u91cf\u90fd\u8f93\u51fa\u8be5\u503c\u3002\",\n        \"parameters\": {\"primary_phase\": \"1/3\", \"primary_estimation_bits\": 6, \"exact_case_phase\": \"5/16\", \"exact_case_estimation_bits\": 4, \"system_eigenstate\": \"1\", \"fourier_sign\": \"+\", \"decoder\": \"inverse QFT\"},\n        \"qubits\": 7,\n        \"elapsed_seconds\": float(perf_counter() - started),\n        \"labels\": approximate[\"labels\"],\n        \"probabilities\": approximate[\"probabilities\"],\n        \"expected_probabilities\": approximate[\"expected_probabilities\"],\n        \"counts\": approximate[\"counts\"],\n        \"shots\": shots,\n        \"seed\": seed,\n        \"max_error\": max(exact[\"max_error\"], approximate[\"max_error\"]),\n        \"validation_passed\": bool(exact[\"validation_passed\"] and approximate[\"validation_passed\"]),\n        \"circuit_text\": approximate[\"circuit_text\"],\n        \"circuit_steps\": [\"\u7cfb\u7edf\u5236\u5907 U=PhaseShift(2\u03c0\u03b8) \u7684\u672c\u5f81\u6001 |1\u27e9\", \"\u8f85\u52a9\u6bd4\u7279\u65bd\u52a0 H\uff0c\u4ea7\u751f\u5747\u5300\u53e0\u52a0\", \"\u6700\u9ad8\u4f4d\u63a7\u5236\u6700\u5927\u5e42\uff0c\u5c06\u76f8\u4f4d\u56de\u8e22\u5230\u8f85\u52a9\u5bc4\u5b58\u5668\", \"\u65bd\u52a0\u8d1f\u89d2\u3001\u9006\u95e8\u5e8f\u7684 F\u2020\", \"\u8ba1\u7b97\u89e3\u6790\u5206\u5e03\u5e76\u7531PennyLane\u5b9e\u9645\u91c7\u6837\"],\n        \"details\": {\n            \"cases\": [exact, approximate],\n            \"primary_case\": \"1/3 with six estimation bits\",\n            \"counts_seed\": seed + 102,\n            \"phase_wave_formula\": \"p(y)=|2^(-m) sum_x exp(2\u03c0i x(\u03b8-y/2^m))|\u00b2\",\n            \"validation_tolerance\": TOLERANCE,\n            \"device\": \"default.qubit CPU state-vector simulator\",\n            \"powered_U_model\": \"\u6b64\u4f8bU\u662f\u5df2\u77e5\u5355\u6bd4\u7279\u76f8\u4f4d\u95e8\uff0c\u76f4\u63a5\u628a\u95e8\u89d2\u4e582^k\u3002\u4e00\u822c\u672a\u77e5U\u9ed1\u7bb1\u4e0d\u80fd\u5047\u5b9a\u514d\u8d39\u5b9e\u73b0\u6240\u6709\u5e42\u3002\",\n        },\n    }\n\n\ndef _modular_multiplication(multiplier: int, modulus: int, system_bits: int) -> np.ndarray:\n    \"\"\"Dense unitary extension of x -> multiplier*x mod modulus.\n\n    Valid x occupy [0, modulus); x >= modulus are fixed.  Requires a unit\n    multiplier modulo modulus.  Columns are input labels, rows outputs.\n    \"\"\"\n    if gcd(multiplier, modulus) != 1:\n        raise ValueError(\"Modular multiplication must use an invertible multiplier.\")\n    size = 2**system_bits\n    if not 1 < modulus <= size:\n        raise ValueError(\"The system register must contain all modular labels.\")\n    matrix = np.zeros((size, size), dtype=complex)\n    for x in range(size):\n        y = multiplier * x % modulus if x < modulus else x\n        matrix[y, x] = 1\n    return matrix\n\n\ndef _continued_fraction(numerator: int, denominator: int) -> tuple[list[int], list[tuple[int, int]]]:\n    terms = []\n    convergents = []\n    p_old, p_previous, q_old, q_previous = 0, 1, 1, 0\n    while denominator:\n        term, remainder = divmod(numerator, denominator)\n        terms.append(int(term))\n        p = term * p_previous + p_old\n        q = term * q_previous + q_old\n        convergents.append((int(p), int(q)))\n        p_old, p_previous = p_previous, p\n        q_old, q_previous = q_previous, q\n        numerator, denominator = denominator, remainder\n    return terms, convergents\n\n\ndef _classical_small_order(a: int, modulus: int) -> tuple[int, list[int]]:\n    \"\"\"Small-instance validation oracle, not part of quantum inference.\"\"\"\n    orbit = []\n    value = 1\n    for order in range(1, modulus + 1):\n        orbit.append(value)\n        value = value * a % modulus\n        if value == 1:\n            return order, orbit\n    raise ArithmeticError(\"No order found for an allegedly invertible multiplier.\")\n\n\ndef _order_demo(seed: int, shots: int) -> dict:\n    started = perf_counter()\n    modulus, a, m, system_bits = 15, 2, 8, 4\n    controls = list(range(m))\n    system = list(range(m, m + system_bits))\n    size = 2**m\n    reference_order, orbit = _classical_small_order(a, modulus)\n    powers = [2 ** (m - index - 1) for index in range(m)]\n    multipliers = [pow(a, power, modulus) for power in powers]\n    matrices = [_modular_multiplication(b, modulus, system_bits) for b in multipliers]\n    matrix_error = max(float(np.max(np.abs(matrix.conj().T @ matrix - np.eye(16)))) for matrix in matrices)\n    device = qml.device(\"default.qubit\", wires=m + system_bits, seed=seed + 200)\n\n    def prepare():\n        qml.BasisState(_basis_bits(1, system_bits), wires=system)\n        for wire in controls:\n            qml.Hadamard(wires=wire)\n        for wire, matrix in zip(controls, matrices):\n            qml.ControlledQubitUnitary(matrix, wires=[wire] + system)\n        qml.adjoint(_qft)(controls)\n\n    @qml.qnode(device)\n    def probabilities_circuit():\n        prepare()\n        return qml.probs(wires=controls)\n\n    @qml.qnode(device)\n    def sample_circuit():\n        prepare()\n        return qml.sample(wires=controls)\n\n    probabilities = np.asarray(probabilities_circuit(), dtype=float)\n    expected = sum(_fourier_probabilities(j / reference_order, m) for j in range(reference_order)) / reference_order\n    max_error = max(matrix_error, float(np.max(np.abs(probabilities - expected))))\n    counts = _sample_counts(sample_circuit, shots, m)\n    recovery = []\n    recovered_denominators = []\n    verified_orders = []\n    for bits, count in counts.items():\n        if count == 0:\n            continue\n        y = int(bits, 2)\n        terms, convergents = _continued_fraction(y, size)\n        candidates = []\n        for p, q in convergents:\n            if 1 < q < modulus:\n                residue = pow(a, q, modulus)\n                verified = residue == 1\n                candidates.append({\"p\": p, \"q\": q, \"a_power_mod_N\": residue, \"passes_mod_power\": verified})\n                if verified:\n                    verified_orders.append(q)\n        phase_fraction = Fraction(y, size)\n        if y != 0:\n            recovered_denominators.append(phase_fraction.denominator)\n        recovery.append({\"bits\": bits, \"y\": y, \"count\": count, \"estimate\": float(y / size), \"reduced_fraction\": str(phase_fraction), \"continued_fraction\": terms, \"candidates\": candidates, \"informative\": y != 0})\n    lcm_candidate = lcm(*recovered_denominators) if recovered_denominators else None\n    lcm_verified = bool(lcm_candidate is not None and pow(a, lcm_candidate, modulus) == 1)\n    inferred_order = min(verified_orders) if verified_orders else lcm_candidate if lcm_verified else None\n    order_matches = inferred_order == reference_order\n    recovery_summary = f\"\u672c\u6b21\u8fde\u5206\u6570\u4e0e\u6a21\u5e42\u9a8c\u8bc1\u5f97\u5230\u9636\u5019\u9009r={inferred_order}\u3002\" if inferred_order is not None else \"\u672c\u6b21\u6709\u9650\u6837\u672c\u5c1a\u672a\u786e\u8ba4\u9636\uff0c\u9700\u8981\u91cd\u590d\u91c7\u6837\u3002\"\n    return {\n        \"id\": \"order\",\n        \"title\": \"\u6a21\u4e58\u6c42\u9636\uff1a\u4ece\u968f\u673a j/r \u6062\u590d\u5468\u671f\",\n        \"note_ref\": \"3.6\",\n        \"source_pages\": [38, 39, 40],\n        \"summary\": \"N=15\u3001a=2\uff0c\u7cfb\u7edf\u76f4\u63a5\u5236\u5907 |0001\u27e9\u30028\u4f4dQPE\u57280\u300164\u3001128\u3001192\u51fa\u73b0\u7b49\u6982\u7387\u5cf0\uff0c\u5206\u522b\u5bf9\u5e94j/4\uff1b\" + recovery_summary + \"\u6b64\u4f8b\u5c55\u793a\u6c42\u9636\u6838\u5fc3\uff0c\u5e76\u975e\u5b8c\u6574\u53ef\u6269\u5c55Shor\u5b9e\u73b0\u3002\",\n        \"parameters\": {\"N\": modulus, \"a\": a, \"estimation_bits\": m, \"system_bits\": system_bits, \"system_initial_state\": \"0001\", \"oracle_dimension\": 16, \"expected_order\": reference_order},\n        \"qubits\": m + system_bits,\n        \"elapsed_seconds\": float(perf_counter() - started),\n        \"labels\": _labels(m),\n        \"probabilities\": probabilities.tolist(),\n        \"expected_probabilities\": expected.tolist(),\n        \"counts\": counts,\n        \"shots\": shots,\n        \"seed\": seed,\n        \"max_error\": max_error,\n        \"validation_passed\": bool(max_error < TOLERANCE and abs(probabilities.sum() - 1) < TOLERANCE and sum(counts.values()) == shots and order_matches),\n        \"circuit_text\": _draw(probabilities_circuit, m + system_bits),\n        \"circuit_steps\": [\"\u7cfb\u7edf4\u4f4d\u5236\u5907 |0001\u27e9\uff0c\u65e0\u9700\u5df2\u77e5\u672c\u5f81\u6001\", \"8\u4f4d\u8f85\u52a9\u5bc4\u5b58\u5668\u5747\u5300\u53e0\u52a0\", \"\u53d7\u63a7\u6a21\u4e58 M_{a^(2^k) mod 15}\uff0c\u6807\u7b7e15\u56fa\u5b9a\", \"\u9006QFT\u540e\u6d4b\u91cf\u8f85\u52a9\u5bc4\u5b58\u5668\", \"\u5bf9\u5b9e\u9645\u6d4b\u5f97y/256\u5c55\u5f00\u8fde\u5206\u6570\u5e76\u9a8c\u8bc12^q mod 15\", \"\u53ef\u5408\u5e76\u5019\u9009\u5206\u6bcd\uff0c\u786e\u8ba4r=4\"],\n        \"details\": {\n            \"sample_seed\": seed + 200,\n            \"orbit\": orbit,\n            \"classical_reference_order\": reference_order,\n            \"inferred_order\": inferred_order,\n            \"hidden_eigenphase_mixture\": [{\"j\": j, \"phase\": float(j / reference_order), \"weight\": float(1 / reference_order)} for j in range(reference_order)],\n            \"peak_labels\": [format(j * size // reference_order, f\"0{m}b\") for j in range(reference_order)],\n            \"controlled_powers_top_to_bottom\": powers,\n            \"modular_multipliers_top_to_bottom\": multipliers,\n            \"unused_basis_states_fixed\": [15],\n            \"matrix_unitarity_error\": matrix_error,\n            \"continued_fraction_observations\": recovery,\n            \"lcm_candidate\": lcm_candidate,\n            \"lcm_mod_power_verified\": lcm_verified,\n            \"verified_order_candidates\": sorted(set(verified_orders)),\n            \"minimality_check\": [{\"proper_divisor\": divisor, \"a_power_mod_N\": pow(a, divisor, modulus)} for divisor in range(1, reference_order) if reference_order % divisor == 0],\n            \"validation_tolerance\": TOLERANCE,\n            \"state_vector_dimension\": 2 ** (m + system_bits),\n            \"state_vector_complex128_bytes\": 16 * 2 ** (m + system_bits),\n            \"oracle_complex128_bytes_each\": 16 * 16 * 16,\n            \"device\": \"default.qubit CPU state-vector simulator\",\n            \"limitations\": \"16\u00d716\u77e9\u9635\u76f4\u63a5\u7f16\u7801\u5c0f\u89c4\u6a21\u6a21\u4e58\uff0c\u5e76\u56fa\u5b9ax\u226515\u3002\u771f\u5b9e\u53ef\u6269\u5c55\u5b9e\u73b0\u5fc5\u987b\u5206\u89e3\u4e3a\u53ef\u9006\u52a0\u6cd5/\u6a21\u4e58\u3001\u63d0\u4f9b\u5e76\u6e05\u7406\u5de5\u4f5c\u6bd4\u7279\uff1b\u6a21\u62df\u72b6\u6001\u5185\u5b58\u968f\u603b\u6bd4\u7279\u6570\u63092^q\u589e\u957f\uff0c\u7a20\u5bc6\u7cfb\u7edforacle\u63094^n\u589e\u957f\u3002\",\n            \"postprocessing_scope\": \"\u672c\u4f8br=4\u6574\u9664256\uff0c\u5cf0\u4e3a\u7cbe\u786e\u6709\u7406\u6570\uff1b\u4e00\u822c\u9636\u4e0d\u6574\u96642^m\u65f6\u8fd8\u9700\u7cbe\u5ea6\u754c\u3001\u8fd1\u4f3c\u8fde\u5206\u6570\u3001\u968f\u673a\u5206\u5b50\u7ea6\u5206\u53ca\u591a\u6b21\u91cd\u8bd5\u3002y=0\u4e0d\u63d0\u4f9b\u9636\u4fe1\u606f\uff0cj=2\u4ec5\u7ed9\u5206\u6bcd2\u3002\",\n        },\n    }\n\n\ndef run(seed: int = 20261012, shots: int = 2048) -> list[dict]:\n    \"\"\"Execute three JSON-serializable demonstration records.\n\n    Each primary case takes `shots` real PennyLane simulator samples. QPE\n    additionally executes its exact case with the same shot count. Seeds\n    are recorded with deterministic offsets to distinguish sample streams.\n    \"\"\"\n    if not isinstance(seed, int) or isinstance(seed, bool) or seed < 0:\n        raise ValueError(\"seed must be a nonnegative integer\")\n    if not isinstance(shots, int) or isinstance(shots, bool) or shots < 1:\n        raise ValueError(\"shots must be a positive integer\")\n    return [_qft_demo(seed, shots), _qpe_demo(seed, shots), _order_demo(seed, shots)]\n", "demo/algorithms/search.py": "\"\"\"Seven-qubit Grover demonstrations with gate oracles and actual CPU sampling.\n\nWire 0 is the most significant bit. Probabilities are in integer order 0..127.\nThe diffusion gate sequence implements -D; hence every iteration is -C rather\nthan C. Its global sign cancels from these uncontrolled measurement experiments.\nThis implementation is not intended for controlled Grover or phase estimation.\n\"\"\"\n\nfrom collections import Counter\nimport math\nimport time\n\nimport numpy as np\nimport pennylane as qml\n\n\nN_QUBITS = 7\nN_STATES = 1 << N_QUBITS\nUNIQUE_MARKED = (73,)\nMULTIPLE_MARKED = (5, 37, 73, 109)\nTOLERANCE = 1e-10\nMAX_UNKNOWN_TRIALS = 32\n\n\ndef _bits(value: int) -> str:\n    \"\"\"Return seven big-endian bits, in the same order as wires 0..6.\"\"\"\n    return format(value, f\"0{N_QUBITS}b\")\n\n\ndef _all_one_phase(wires: tuple[int, ...]) -> None:\n    \"\"\"Flip only the all-one basis amplitude: H(target), MCX, H(target).\"\"\"\n    qml.Hadamard(wires=wires[-1])\n    qml.MultiControlledX(wires=wires)\n    qml.Hadamard(wires=wires[-1])\n\n\ndef _phase_oracle(marked: tuple[int, ...], wires: tuple[int, ...]) -> None:\n    \"\"\"Implement (-1)^f(x), with one phase flip for each distinct marked x.\n\n    An X on each zero bit maps the marked bit string to all ones. The final X\n    gates restore every bit. No diagonal matrix or hand-generated state is used.\n    \"\"\"\n    for value in marked:\n        zero_wires = tuple(w for w, bit in zip(wires, _bits(value)) if bit == \"0\")\n        for wire in zero_wires:\n            qml.PauliX(wires=wire)\n        _all_one_phase(wires)\n        for wire in zero_wires:\n            qml.PauliX(wires=wire)\n\n\ndef _diffusion(wires: tuple[int, ...]) -> None:\n    \"\"\"Apply -D = H^n X^n (multi-controlled Z) X^n H^n, with no work bits.\"\"\"\n    for wire in wires:\n        qml.Hadamard(wires=wire)\n    for wire in wires:\n        qml.PauliX(wires=wire)\n    _all_one_phase(wires)\n    for wire in wires:\n        qml.PauliX(wires=wire)\n    for wire in wires:\n        qml.Hadamard(wires=wire)\n\n\ndef _make_nodes(marked: tuple[int, ...], seed: int):\n    \"\"\"Create analytic and sampling QNodes; both prepare and run actual gates.\"\"\"\n    wires = tuple(range(N_QUBITS))\n    analytic_device = qml.device(\"default.qubit\", wires=wires)\n    sample_device = qml.device(\"default.qubit\", wires=wires, seed=seed)\n\n    def operations(iterations: int) -> None:\n        for wire in wires:\n            qml.Hadamard(wires=wire)\n        for _ in range(iterations):\n            _phase_oracle(marked, wires)\n            _diffusion(wires)\n\n    @qml.qnode(analytic_device)\n    def probabilities(iterations: int):\n        operations(iterations)\n        return qml.probs(wires=wires)\n\n    @qml.qnode(sample_device)\n    def samples(iterations: int):\n        operations(iterations)\n        return qml.sample(wires=wires)\n\n    return probabilities, samples\n\n\ndef _theory(marked: tuple[int, ...], iterations: int) -> tuple[np.ndarray, float]:\n    \"\"\"Independent rotation prediction; a 128-vector and total success rate.\n\n    Each marked state has probability sin\u00b2((2t+1)\u03b8)/s. All other states have\n    probability cos\u00b2((2t+1)\u03b8)/(128-s), with \u03b8=arcsin(sqrt(s/128)).\n    \"\"\"\n    s = len(marked)\n    theta = math.asin(math.sqrt(s / N_STATES))\n    success = math.sin((2 * iterations + 1) * theta) ** 2\n    expected = np.full(N_STATES, (1 - success) / (N_STATES - s), dtype=float)\n    expected[list(marked)] = success / s\n    return expected, success\n\n\ndef _sample_counts(node, iterations: int, shots: int) -> dict[str, int]:\n    \"\"\"Count actual qml.sample basis draws, never synthetic probability counts.\"\"\"\n    raw = np.asarray(qml.set_shots(node, shots=shots)(iterations), dtype=int)\n    if raw.shape != (shots, N_QUBITS):\n        raise ValueError(f\"Unexpected sample shape {raw.shape}; wanted {(shots, N_QUBITS)}\")\n    if np.any((raw != 0) & (raw != 1)):\n        raise ValueError(\"Nonbinary basis measurement returned by device\")\n    counts = Counter(\"\".join(str(int(bit)) for bit in row) for row in raw)\n    return dict(sorted(counts.items()))\n\n\ndef _known_case(marked: tuple[int, ...], seed: int, shots: int) -> dict:\n    \"\"\"Execute 17 analytic QNode calls, then sample the selected stopping point.\"\"\"\n    theta = math.asin(math.sqrt(len(marked) / N_STATES))\n    optimal = math.floor(math.pi / (4 * theta))\n    probability_node, sample_node = _make_nodes(marked, seed)\n    curve = []\n    maximum_error = 0.0\n    selected = None\n    selected_expected = None\n    for iterations in range(17):\n        observed = np.asarray(probability_node(iterations), dtype=float)\n        expected, theory_success = _theory(marked, iterations)\n        if observed.shape != (N_STATES,):\n            raise ValueError(f\"Unexpected analytic probability shape {observed.shape}\")\n        maximum_error = max(\n            maximum_error,\n            float(np.max(np.abs(observed - expected))),\n            float(abs(observed.sum() - 1)),\n        )\n        curve.append(\n            dict(\n                iterations=iterations,\n                success_probability=float(observed[list(marked)].sum()),\n                theory=float(theory_success),\n            )\n        )\n        if iterations == optimal:\n            selected, selected_expected = observed, expected\n    if selected is None or selected_expected is None:\n        raise RuntimeError(\"Chosen stopping point is outside the executed curve\")\n    counts = _sample_counts(sample_node, optimal, shots)\n    sampled_successes = sum(counts.get(_bits(value), 0) for value in marked)\n    return dict(\n        marked=list(marked),\n        optimal_iterations=optimal,\n        parameters={\"n\": N_QUBITS, \"N\": N_STATES, \"s\": len(marked), \"theta\": theta},\n        qubits=N_QUBITS,\n        labels=[_bits(x) for x in range(N_STATES)],\n        probabilities=selected.tolist(),\n        expected_probabilities=selected_expected.tolist(),\n        counts=counts,\n        shots=shots,\n        seed=seed,\n        success_probability=float(selected[list(marked)].sum()),\n        sampled_successes=sampled_successes,\n        sampled_success_probability=sampled_successes / shots,\n        max_error=float(maximum_error),\n        validation_passed=bool(maximum_error <= TOLERANCE and sum(counts.values()) == shots),\n        curve=curve,\n        circuit_text=qml.draw(probability_node, max_length=110)(optimal),\n    )\n\n\ndef _unknown_search(seed: int) -> tuple[list[dict], dict]:\n    \"\"\"Bounded BBHT-style trial trace, without using s to choose iterations.\n\n    Each trial checks one uniformly chosen classical candidate, then, if needed,\n    draws j uniformly from 0..ceil(T)-1 and performs an actual one-shot QNode.\n    The seven-bit oracle is fixed internally. Its cardinality is not supplied to\n    the selection rule. The 32-trial limit is a demo budget, not a no-solution\n    proof. A run that exhausts it returns success=False.\n    \"\"\"\n    marked = MULTIPLE_MARKED\n    _, sample_node = _make_nodes(marked, seed + 2)\n    rng = np.random.default_rng(seed)\n    scale = 1.0\n    maximum_scale = math.sqrt(N_STATES)\n    growth = 1.25\n    trace = []\n    total_queries = 0\n    found = None\n    method = None\n    for trial in range(1, MAX_UNKNOWN_TRIALS + 1):\n        length = math.ceil(scale)\n        candidate = int(rng.integers(N_STATES))\n        classical_verified = candidate in marked\n        record = dict(\n            trial=trial,\n            window_scale=float(scale),\n            window_length=length,\n            classical_candidate=candidate,\n            classical_bits=_bits(candidate),\n            classical_verified=classical_verified,\n            iterations=0,\n            quantum_candidate=None,\n            quantum_bits=None,\n            quantum_verified=False,\n            quantum_counts={},\n            oracle_queries=1,\n        )\n        if classical_verified:\n            found, method = candidate, \"classical_candidate_verification\"\n        else:\n            iterations = int(rng.integers(length))\n            counts = _sample_counts(sample_node, iterations, 1)\n            bits = next(iter(counts))\n            quantum_candidate = int(bits, 2)\n            quantum_verified = quantum_candidate in marked\n            record.update(\n                iterations=iterations,\n                quantum_candidate=quantum_candidate,\n                quantum_bits=bits,\n                quantum_verified=quantum_verified,\n                quantum_counts=counts,\n                oracle_queries=iterations + 2,\n            )\n            if quantum_verified:\n                found, method = quantum_candidate, \"quantum_sample_verification\"\n        total_queries += record[\"oracle_queries\"]\n        trace.append(record)\n        if found is not None:\n            break\n        scale = min(growth * scale, maximum_scale)\n\n    result = dict(\n        success=found is not None,\n        found_value=found,\n        found_bits=_bits(found) if found is not None else None,\n        method=method,\n        trials_used=len(trace),\n        max_trials=MAX_UNKNOWN_TRIALS,\n        initial_window=1.0,\n        growth_factor=growth,\n        window_cap=maximum_scale,\n        shots_per_quantum_trial=1,\n        seed=seed,\n        quantum_device_seed=seed + 2,\n        total_oracle_queries=total_queries,\n        hidden_marked=list(marked),\n        stopping_rule=\"\u5df2\u9a8c\u8bc1\u89e3\u624d\u8f93\u51fa\uff1b32\u6b21\u5c1d\u8bd5\u7528\u5c3d\u65f6\u62a5\u544a\u672a\u627e\u5230\uff0c\u4e0d\u8bc1\u660e\u65e0\u89e3\u3002\",\n    )\n    return trace, result\n\n\ndef run(seed: int = 20261012, shots: int = 2048) -> list[dict]:\n    \"\"\"Return one JSON-safe Grover display record, including all three cases.\n\n    ``probabilities`` and ``expected_probabilities`` have 128 entries in big-endian\n    integer order. ``counts`` holds actual samples. Errors compare analytic QNode\n    probabilities to independent rotation formulas; sampling frequencies are\n    intentionally not required to equal those exact probabilities.\n    \"\"\"\n    if isinstance(seed, bool) or not isinstance(seed, int) or seed < 0:\n        raise ValueError(\"seed must be a nonnegative integer\")\n    if isinstance(shots, bool) or not isinstance(shots, int) or shots < 1:\n        raise ValueError(\"shots must be a positive integer\")\n    start = time.perf_counter()\n    unique = _known_case(UNIQUE_MARKED, seed, shots)\n    multiple = _known_case(MULTIPLE_MARKED, seed + 1, shots)\n    unknown_trace, unknown_trials = _unknown_search(seed)\n    found = unknown_trials[\"found_value\"]\n    trace_valid = (\n        len(unknown_trace) <= MAX_UNKNOWN_TRIALS\n        and all(item[\"iterations\"] <= math.sqrt(N_STATES) for item in unknown_trace)\n        and (found is None or found in MULTIPLE_MARKED)\n    )\n    maximum_error = max(unique[\"max_error\"], multiple[\"max_error\"])\n    return [\n        dict(\n            id=\"grover\",\n            title=\"Grover\uff1a\u627e\u5230\u89e3\uff0c\u4e5f\u8981\u5728\u6b63\u786e\u8f6e\u6b21\u505c\u6b62\",\n            note_ref=\"4.1\u20134.7\",\n            source_pages=list(range(41, 51)),\n            summary=(\n                \"7\u4f4d128\u4e2a\u5019\u9009\u4e2d\u641c\u7d2273\uff1a8\u8f6e\u540e\u89e3\u6790\u6210\u529f\u6982\u7387\u7ea699.56%\uff1b\"\n                \"\u56db\u89e3\u53ea\u97004\u8f6e\uff0c\u6cbf\u75288\u8f6e\u4f1a\u964d\u81f3\u7ea61.45%\u3002\u66f2\u7ebf\u6765\u81ea\u771f\u5b9e\u95e8\u7535\u8def\uff0c\"\n                \"\u67f1\u56fe\u8ba1\u6570\u6765\u81ea\u6709\u9650\u6b21\u6d4b\u91cf\uff1b\u672a\u77e5\u89e3\u6570\u53e6\u663e\u793a\u5b9e\u9645\u9010\u8f6e\u9a8c\u8bc1\u8bb0\u5f55\u3002\"\n            ),\n            parameters={\n                \"n\": N_QUBITS,\n                \"N\": N_STATES,\n                \"marked\": list(UNIQUE_MARKED),\n                \"s\": 1,\n                \"iterations\": unique[\"optimal_iterations\"],\n                \"curve_iterations\": [0, 16],\n                \"comparison_tolerance\": TOLERANCE,\n            },\n            qubits=N_QUBITS,\n            elapsed_seconds=float(time.perf_counter() - start),\n            labels=unique[\"labels\"],\n            probabilities=unique[\"probabilities\"],\n            expected_probabilities=unique[\"expected_probabilities\"],\n            counts=unique[\"counts\"],\n            shots=shots,\n            seed=seed,\n            max_error=float(maximum_error),\n            validation_passed=bool(\n                unique[\"validation_passed\"] and multiple[\"validation_passed\"] and trace_valid\n            ),\n            circuit_text=unique[\"circuit_text\"],\n            circuit_steps=[\n                \"\u4e03\u4f4d\u90fd\u65bd\u52a0H\uff0c\u51c6\u5907128\u4e2a\u5019\u9009\u7684\u5747\u5300\u53e0\u52a0\u3002\",\n                \"\u6309\u76ee\u6807\u6bd4\u7279\u7ffbX\uff0c\u7528H\u2014\u591a\u63a7X\u2014H\u5b9e\u73b0\u76ee\u6807\u6001\u76f8\u4f4d\u7ffb\u8f6c\uff0c\u518d\u590d\u539f\u3002\",\n                \"\u65bd\u52a0H\u2014X\u2014\u591a\u63a7Z\u2014X\u2014H\u6269\u6563\uff1b\u672c\u7535\u8def\u5b9e\u73b0\u2212D\uff0c\u5168\u5c40\u8d1f\u53f7\u4e0d\u5f71\u54cd\u672c\u5b9e\u9a8c\u3002\",\n                \"\u552f\u4e00\u89e3\u91cd\u590d8\u8f6e\uff1b\u56db\u89e3\u91cd\u590d4\u8f6e\uff1b\u53e6\u72ec\u7acb\u6267\u884c0\u81f316\u8f6e\u4ee5\u67e5\u770b\u8fc7\u65cb\u8f6c\u3002\",\n                \"\u8ba1\u7b97\u7cbe\u786eqml.probs\uff0c\u5e76\u53e6\u5916\u7528qml.sample\u4ea7\u751f\u5b9e\u9645\u6d4b\u91cf\u8ba1\u6570\u3002\",\n                \"\u672a\u77e5\u89e3\u6570\u53ea\u6309\u589e\u957f\u7a97\u53e3\u53d6\u6b21\u6570\uff0c\u6bcf\u6b21\u5b9e\u9645\u6d4b\u91cf\u540e\u9a8c\u8bc1\u5019\u9009\uff0c\u6700\u591a32\u6b21\u3002\",\n            ],\n            details={\n                \"backend\": \"default.qubit (CPU)\",\n                \"bit_order\": \"wire 0\u4e3a\u6700\u9ad8\u4f4d\uff0c\u6807\u7b7e\u4e3ax6\u2026x0\uff0c\u7d22\u5f150\u2026127\",\n                \"phase_convention\": \"\u5b9e\u9645\u6bcf\u8f6e\u4e3a\u2212C\uff1b\u672a\u7528\u4e8e\u53d7\u63a7Grover\u6216\u76f8\u4f4d\u4f30\u8ba1\u3002\",\n                \"success_probability\": unique[\"success_probability\"],\n                \"sampled_successes\": unique[\"sampled_successes\"],\n                \"sampled_success_probability\": unique[\"sampled_success_probability\"],\n                \"curve\": unique[\"curve\"],\n                \"multiple_case\": multiple,\n                \"unknown_trace\": unknown_trace,\n                \"unknown_trials\": unknown_trials,\n                \"validation_scope\": (\n                    \"\u8bef\u5dee\u6bd4\u8f83\u5b9e\u9645qml.probs\u4e0e\u72ec\u7acb\u65cb\u8f6c\u516c\u5f0f\uff0c\u5e76\u68c0\u67e5\u6d4b\u91cf\u6570\u91cf\u3001\u672a\u77e5\u7b56\u7565\u9884\u7b97\u548c\u8f93\u51fa\u9a8c\u8bc1\u3002\"\n                    \"\u672a\u77e5\u7b56\u7565success\u53e6\u5217\uff0c\u6709\u9650\u5c1d\u8bd5\u5931\u8d25\u4e0d\u4f1a\u88ab\u6539\u5199\u4e3a\u6210\u529f\u3002\"\n                ),\n            },\n        )\n    ]\n", "demo/requirements.txt": "appdirs==1.4.4\nautograd==1.8.0\nautoray==0.8.4\ncachetools==7.2.1\ncertifi==2026.7.22\ncharset-normalizer==3.5.2\ncontourpy==1.4.0\ncycler==0.12.1\ndiastatic-malt==2.15.3\nfonttools==4.66.1\ngast==0.7.0\nidna==3.20\nkiwisolver==1.5.1\nmatplotlib==3.11.2\nnetworkx==3.7\nnumpy==2.5.4\npackaging==26.3\npennylane==0.45.1\npennylane_lightning==0.45.0\npillow==12.3.0\npsutil==7.2.2\npyparsing==3.3.3\npython-dateutil==2.9.0.post0\nrequests==2.34.2\nrustworkx==0.18.1\nscipy==1.18.1\nscipy-openblas32==0.3.34.237.0\nsix==1.17.0\ntermcolor==3.3.0\ntomlkit==0.15.1\ntyping_extensions==4.16.0\nurllib3==2.8.0\n", "demo/README.md": "# Quantum algorithms: numerical experiments\n\nThe experiments accompany the four-chapter lecture notes. All outputs are ideal classical state-vector simulations with PennyLane default.qubit on the CPU. Counts come from actual qml.sample calls, separate from exact simulator probabilities and independent analytical references.\n\n## Website and notes\n\nOpen site/dist/index.html directly for offline use. Alternatively, from the project root:\n\n```powershell\ndemo/.venv/Scripts/python.exe -m http.server 8765 --bind 127.0.0.1 --directory demo/site/dist\n```\n\nVisit http://127.0.0.1:8765/ . The private companion is https://quantum-algorithms-qc-note-oct13.woodsyloach.chatgpt.site ; sign in with the owning ChatGPT account. Controls browse retained results. The website has no quantum execution backend.\n\nThe English v0.2 PDF revises the validated v0.1 mathematics. Frozen batch local-demo-002 records the original v0.1 PDF hash; the website manifest records the displayed note separately. Packaging does not rewrite run provenance or claim a new experiment.\n\n## Environment and reproduction\n\nPython 3.12 and the exact dependencies in requirements.txt were used. Create an environment from the project root (installation needs network access):\n\n```powershell\npython -m venv demo/.venv\ndemo/.venv/Scripts/python.exe -m pip install -r demo/requirements.txt\n```\n\nExecute a new batch and package the website:\n\n```powershell\ndemo/.venv/Scripts/python.exe demo/run_demo.py --run-id local-demo-003 --shots 2048 --seed 20261012\ndemo/.venv/Scripts/python.exe demo/build_site.py --run-id local-demo-003 --note-version 0.2\n```\n\nThe runner refuses to overwrite batches and limits shots to 128\u20138192. It retains four complete calculation-source snapshots, hashes, parameters, counts, environment, and the original note manifest. Identical seeds do not establish determinism across versions or machines. Source downloads include the original manifest required by the tested runner. Calculation code is unchanged during this revision.\n\n## Implementations and conventions\n\n| File and algorithm | Executed example | Lecture chapter |\n|---|---|---|\n| algorithms/query.py: Deutsch | 2 wires, all four Boolean functions | 1 |\n| Deutsch\u2013Jozsa | 4 input + 1 target; constant and balanced | 1 |\n| Bernstein\u2013Vazirani | 6 input + 1 target; coefficient 101101 | 1 |\n| Simon | 4 input + 4 output; sampled GF(2) constraints, period 1011 and injective control | 1 |\n| algorithms/phase.py: QFT | 3 wires; positive exponent and inverse round trip | 3 |\n| QPE | Phase 5/16 with 4 estimation bits; phase 1/3 with 6 bits | 3 |\n| Order finding | N=15, a=2; 8 estimation + 4 system wires | 3 |\n| algorithms/search.py: Grover | N=128; one/four marked states, 0\u201316 iterations, unknown-count trials | 4 |\n\nWire 0 is the most significant bit; labels are big-endian. QFT has a positive exponent and final bit reversal. QPE uses its adjoint. The bit oracle preserves its input and XORs the function value into a target.\n\nProbability error is the maximum absolute component difference between exact simulator and independent reference probability vectors. QFT also compares complex amplitudes componentwise and checks the inverse round trip. Order finding checks modular permutation matrices and postprocessing. Sample frequencies have statistical uncertainty; floating-point tolerances apply to exact calculations.\n\n## Retained outputs and limits\n\nThe displayed batch is results/local-demo-002/: JSON, full CSV, tested snapshots, and exportable plots. Batch 001 remains historical evidence. Main cases use 2048 shots; the largest circuit has 12 qubits. Hardware and four CPU benchmark points remain in hardware.json and benchmark.json. RSS is a reading after execution, not peak memory. GPU detection is not a GPU benchmark; simulations use the CPU.\n\nOrder finding uses 16\u00d716 dense modular-multiplication matrices for teaching; scalable Shor arithmetic is not implemented. The Grover decomposition has a global sign per iteration that must be accounted for in controlled use. Finite unsuccessful retries do not prove absence of solutions. Reproduction depends on source and dependency conventions, in addition to the seed.\n\n## Hosted version maintenance\n\nsite/.openai/hosting.json retains the existing Sites ID; reuse it for updates. site/ has its own Git repository; the project root does not. Deployment metadata is in ../review/site_publication.json and later revision records.\n\nValidate the site and data before source saving/pushing and private deployment. On Windows without Bash, ../tools/package_site_windows.py --prepare-helper <absolute-path-to-Sites-prepare-site-build.cjs> uses the unchanged official Node validator and Python tarfile for clean, already-pushed static source. It retains the archive and hash and stores no credentials. Packaging alone does not deploy.\n\nPennyLane references: [default.qubit](https://docs.pennylane.ai/en/stable/code/api/pennylane.devices.default_qubit.DefaultQubit.html), [ControlledQubitUnitary](https://docs.pennylane.ai/en/stable/code/api/pennylane.ControlledQubitUnitary.html), [QFT](https://docs.pennylane.ai/en/stable/code/api/pennylane.QFT.html). Exact versions are locked in requirements.txt.\n", "demo/benchmark.py": "\"\"\"Short CPU state-vector trials; no gradients, no remote quantum devices.\"\"\"\nimport os\nfor name in ['OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS']:\n    os.environ.setdefault(name,'4')\nimport time\nimport json\nfrom pathlib import Path\nimport pennylane as qml\nimport numpy as np\nimport psutil\n\ndef run():\n    rows=[]\n    for n in [8,12,16,20]:\n        dev=qml.device('default.qubit',wires=n,seed=20261012)\n        @qml.qnode(dev,interface=None)\n        def circuit():\n            for layer in range(3):\n                for w in range(n):\n                    qml.Hadamard(wires=w)\n                    qml.RY(0.13*(w+1)/(layer+1),wires=w)\n                for w in range(n-1):qml.CNOT(wires=[w,w+1])\n            return qml.state()\n        start=time.perf_counter(); state=circuit(); elapsed=time.perf_counter()-start\n        error=abs(float(np.vdot(state,state).real)-1)\n        if error>1e-10:raise AssertionError(f'normalization failed at {n} wires')\n        rows.append({'qubits':n,'layers':3,'elapsed_seconds':elapsed,\n                     'state_vector_bytes':int(state.nbytes),\n                     'process_rss_after_bytes':psutil.Process().memory_info().rss,\n                     'normalization_error':error})\n        print(f'CPU benchmark: {n} wires, {elapsed:.3f}s',flush=True)\n        del state\n        if elapsed>8:\n            break\n    return {'backend':'default.qubit (CPU)','trials':rows,\n            'blas_thread_limit':4,'seed':20261012,\n            'scope':'One forward execution per point; import time excluded. RSS is an after-run reading, not a peak-memory measurement.',\n            'decision':'Demo circuits at most 12 qubits; benchmarks do not establish the maximum feasible size or GPU performance.'}\n\nif __name__=='__main__':\n    result=run(); path=Path(__file__).resolve().parent/'benchmark.json'\n    path.write_text(json.dumps(result,indent=2),encoding='utf-8')\n", "demo/build_site.py": "\"\"\"Package actual retained results for a buildless, offline-capable website.\"\"\"\nfrom pathlib import Path\nimport argparse\nimport json\nimport shutil\nimport zipfile\nimport hashlib\nimport os\nos.environ.setdefault('MPLCONFIGDIR',str(Path(__file__).resolve().parent.parent/'build'/'matplotlib'))\nimport matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\nimport numpy as np\n\nROOT=Path(__file__).resolve().parent\nPROJECT=ROOT.parent\n\ndef main():\n    p=argparse.ArgumentParser();p.add_argument('--run-id',default='local-demo-001');p.add_argument('--note-version',choices=['0.1','0.2'],default='0.1');args=p.parse_args()\n    if not args.run_id.replace('-','').replace('_','').isalnum():raise ValueError('Invalid run id')\n    batch=ROOT/'results'/args.run_id\n    data=json.loads((batch/'results.json').read_text(encoding='utf-8'))\n    dist=ROOT/'site'/'dist';assets=dist/'assets';target=dist/'data'\n    for path in [assets,target]:path.mkdir(parents=True,exist_ok=True)\n    shutil.copyfile(batch/'results.json',target/'results.json')\n    (target/'results.js').write_text('window.DEMO_RESULTS = '+json.dumps(data,ensure_ascii=False,allow_nan=False)+';\\n',encoding='utf-8')\n    original_note=PROJECT/'output'/'pdf'/'quantum_algorithms_v0.1.pdf'\n    if hashlib.sha256(original_note.read_bytes()).hexdigest()!=data['note']['pdf_sha256']:\n        raise ValueError('Current note differs from the note used by this run')\n    note=PROJECT/'output'/'pdf'/f'quantum_algorithms_v{args.note_version}.pdf'\n    manifest=json.loads((PROJECT/'output'/'pdf'/('manifest_v0.2.json' if args.note_version=='0.2' else 'manifest.json')).read_text(encoding='utf-8'))\n    if hashlib.sha256(note.read_bytes()).hexdigest()!=manifest['pdf_sha256']:raise ValueError('Display note manifest does not match its PDF')\n    shutil.copyfile(note,assets/note.name)\n    shutil.copyfile(note.with_suffix('.tex'),assets/note.with_suffix('.tex').name)\n    sources={}\n    for relative,expected_hash in data['source_sha256'].items():\n        file=batch/'source'/Path(relative).relative_to('demo')\n        contents=file.read_bytes()\n        if hashlib.sha256(contents).hexdigest()!=expected_hash:raise ValueError(f'Source snapshot mismatch: {relative}')\n        if (PROJECT/relative).read_bytes()!=contents:raise ValueError(f'Active calculation differs from frozen snapshot: {relative}')\n        sources[relative.replace('\\\\','/')]=contents.decode('utf-8')\n    for relative in ['demo/requirements.txt','demo/README.md','demo/benchmark.py','demo/build_site.py','tools/validate_notes.py']:\n        sources[relative]=(PROJECT/relative).read_text(encoding='utf-8')\n    (target/'sources.js').write_text('window.DEMO_SOURCES = '+json.dumps(sources,ensure_ascii=True)+';\\n',encoding='utf-8')\n    figures=batch/'figures';figures.mkdir(exist_ok=True)\n    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':9,'axes.spines.top':False,'axes.spines.right':False,'svg.fonttype':'none'})\n    fig,axs=plt.subplots(4,2,figsize=(11,11),layout='constrained')\n    for ax,item in zip(axs.ravel(),data['algorithms']):\n        values=np.array(item['probabilities']);theory=np.array(item['expected_probabilities'])\n        indices=np.argsort(values)[-min(12,len(values)):];indices=np.sort(indices)\n        labels=[item['labels'][i] for i in indices];counts=np.array([item['counts'].get(x,0)/item['shots'] for x in labels])\n        x=np.arange(len(indices));ax.bar(x-.17,values[indices],.34,label='Exact simulator',color='#2c7375')\n        ax.bar(x+.17,counts,.34,label='Sample frequency',color='#cc6a46')\n        ax.plot(x,theory[indices],'_',color='#182f33',markersize=6,label='Independent theory')\n        ax.set_xticks(x,labels,rotation=45,ha='right',fontsize=7);ax.set_ylim(0,max(0.05,max(values[indices])*1.18));ax.set_ylabel('Probability')\n        ax.set_title(f\"{item['id'].upper()} | {item['qubits']} wires | {item['shots']} shots\",loc='left',fontsize=10)\n    axs[0,0].legend(frameon=False,fontsize=7)\n    fig.suptitle(f\"Quantum algorithms: local PennyLane run {args.run_id}\\nTop 12 states per panel; ideal CPU simulation\",fontsize=13)\n    for ext in ['svg','png']:fig.savefig(figures/f'probability_overview.{ext}',dpi=180)\n    plt.close(fig)\n    grover=next(x for x in data['algorithms'] if x['id']=='grover')\n    fig,ax=plt.subplots(figsize=(8,4.4),layout='constrained')\n    for name,curve,color in [('1 marked state',grover['details']['curve'],'#2c7375'),('4 marked states',grover['details']['multiple_case']['curve'],'#bc4926')]:\n        ax.plot([x['iterations'] for x in curve],[x['success_probability'] for x in curve],'o-',label=name,color=color,markersize=4)\n    ax.set(xlabel='Grover iterations t',ylabel='Success probability',ylim=(0,1.03),title='N=128: success oscillates; more iterations can overshoot')\n    ax.legend(frameon=False);ax.grid(alpha=.18)\n    for ext in ['svg','png']:fig.savefig(figures/f'grover_iterations.{ext}',dpi=180)\n    plt.close(fig)\n    for source in figures.iterdir():shutil.copyfile(source,assets/source.name)\n    with zipfile.ZipFile(assets/'demo_source.zip','w',compression=zipfile.ZIP_DEFLATED) as archive:\n        normalized_hashes={name.replace('\\\\','/'):value for name,value in data['source_sha256'].items()}\n        for pattern in ['*.py','*.ps1','requirements.txt','README.md','hardware.json','benchmark.json','algorithms/*.py']:\n            for file in ROOT.glob(pattern):\n                relative=file.relative_to(PROJECT).as_posix()\n                if relative in normalized_hashes:\n                    archive.write(batch/'source'/Path(relative).relative_to('demo'),relative)\n                else:archive.write(file,relative)\n        for filename in ['manifest.json','quantum_algorithms_v0.1.pdf','quantum_algorithms_v0.1.tex']:\n            archive.write(PROJECT/'output/pdf'/filename,'output/pdf/'+filename)\n        if args.note_version=='0.2':\n            for filename in ['manifest_v0.2.json','quantum_algorithms_v0.2.pdf','quantum_algorithms_v0.2.tex']:\n                archive.write(PROJECT/'output/pdf'/filename,'output/pdf/'+filename)\n        archive.write(PROJECT/'tools/validate_notes.py','tools/validate_notes.py')\n        for filename in ['index.html','style.css','app.js','icon.svg']:\n            archive.write(dist/filename,'demo/site/dist/'+filename)\n    (dist/'site_manifest.json').write_text(json.dumps({'run_id':args.run_id,'results_sha256':hashlib.sha256((batch/'results.json').read_bytes()).hexdigest(),\n                    'note_sha256':manifest['pdf_sha256'],'display_note_version':args.note_version,'display_note_pages':manifest['pages'],\n                    'original_run_note_sha256':data['note']['pdf_sha256'],\n                    'source_sha256':data['source_sha256'],\n                    'data_kind':'executed local PennyLane results; no live browser simulation'},indent=2),encoding='utf-8')\n    print(f'Packaged local website: {dist}')\n\nif __name__=='__main__':main()\n", "tools/validate_notes.py": "\"\"\"Independent small-state checks for the manuscript's mathematical conventions.\n\nAll basis indices are big-endian integers; gates are applied left-to-right.\nThis script uses NumPy independently of any later PennyLane demo.\n\"\"\"\nfrom pathlib import Path\nimport json\nimport math\nimport argparse\nimport numpy as np\n\nROOT = Path(__file__).resolve().parents[1]\nTOL = 1e-12\nchecks = []\n\ndef record(name, cases, error, details):\n    if error > TOL:\n        raise AssertionError(f\"{name}: {error} > {TOL}\")\n    checks.append(dict(name=name, cases=cases, max_error=float(error), tolerance=TOL, details=details))\n\ndef hmatrix(n):\n    h = np.array([[1, 1], [1, -1]], dtype=complex)/np.sqrt(2)\n    out = np.ones((1,1), dtype=complex)\n    for _ in range(n):\n        out = np.kron(out, h)\n    return out\n\ndef qft(n):\n    N = 1 << n\n    j = np.arange(N)\n    return np.exp(2j*np.pi*j[:,None]*j[None,:]/N)/np.sqrt(N)\n\ndef apply_h_rows(matrix, wire, n):\n    mask = 1 << (n-1-wire)\n    for i in range(1 << n):\n        if not i & mask:\n            a, b = matrix[i].copy(), matrix[i | mask].copy()\n            matrix[i], matrix[i | mask] = (a+b)/np.sqrt(2), (a-b)/np.sqrt(2)\n\ndef swap_rows(matrix, w1, w2, n):\n    m1, m2 = 1 << (n-1-w1), 1 << (n-1-w2)\n    mapping = [i ^ (m1|m2) if bool(i&m1) != bool(i&m2) else i for i in range(1<<n)]\n    matrix[:] = matrix[mapping]\n\ndef standard_qft(n):\n    M = np.eye(1<<n,dtype=complex)\n    for w in range(n):\n        apply_h_rows(M,w,n)\n        for control in range(w+1,n):\n            angle=2*np.pi/(1 << (control-w+1))\n            for i in range(1<<n):\n                if (i >> (n-1-w))&1 and (i >> (n-1-control))&1:\n                    M[i] *= np.exp(1j*angle)\n    for w in range(n//2):\n        swap_rows(M,w,n-1-w,n)\n    return M\n\ndef recursive_qft(n):\n    if n == 1:\n        return hmatrix(1)\n    N=1<<n\n    M=np.kron(recursive_qft(n-1),np.eye(2))\n    for i in range(N):\n        y,a=divmod(i,2)\n        M[i]*=np.exp(2j*np.pi*a*y/N)\n    apply_h_rows(M,n-1,n)\n    for w in range(n-2,-1,-1):\n        swap_rows(M,w,w+1,n)\n    return M\n\ndef query_checks():\n    cases=0; err=0\n    # Deutsch/DJ and BV: build the joint XOR oracle state explicitly.\n    for n in range(1,4):\n        N=1<<n; H=hmatrix(n)\n        for truth in range(1<<N):\n            f=np.array([(truth>>x)&1 for x in range(N)])\n            if int(f.sum()) not in [0,N//2,N]:\n                continue\n            state=np.tile(np.array([1,-1])/np.sqrt(2*N),(N,1)).astype(complex)\n            for x in range(N):\n                if f[x]: state[x]=state[x,::-1]\n            output=H@state; p=np.sum(np.abs(output)**2,axis=1)\n            expect=float(f.sum() in [0,N])\n            err=max(err,abs(p[0]-expect),abs(p.sum()-1)); cases+=1\n    record(\"Deutsch / Deutsch-Jozsa promised functions\",cases,err,\"n=1..3; all promised truth tables; explicit joint XOR action\")\n    cases=0; err=0\n    for n in range(1,6):\n        N=1<<n; H=hmatrix(n)\n        for s in range(N):\n            f=np.array([(x&s).bit_count()%2 for x in range(N)])\n            out=H@((-1.)**f/np.sqrt(N)); p=np.abs(out)**2\n            expect=np.eye(N)[s]\n            err=max(err,float(np.max(np.abs(p-expect)))); cases+=1\n    record(\"Bernstein-Vazirani\",cases,err,\"n=1..5; every secret; big-endian output integer s\")\n    cases=0; err=0\n    for n in range(1,5):\n        N=1<<n; H=hmatrix(n)\n        for s in range(N):\n            state=np.zeros((N,N),complex)\n            for x in range(N):\n                f=x if s==0 else min(x,x^s)\n                state[x,f]=1/np.sqrt(N)\n            p=np.sum(np.abs(H@state)**2,axis=1)\n            expect=np.full(N,1/N) if s==0 else np.array([2/N if (y&s).bit_count()%2==0 else 0 for y in range(N)])\n            err=max(err,float(np.max(np.abs(p-expect))),abs(p.sum()-1)); cases+=1\n    record(\"Simon\",cases,err,\"n=1..4; every period including zero; output-register marginal, not a guessed pure input state\")\n\nquery_checks()\nerr=0\nfor n in range(1,6):\n    F=qft(n)\n    err=max(err,np.max(np.abs(standard_qft(n)-F)),np.max(np.abs(recursive_qft(n)-F)))\nrecord(\"QFT gate order / permutations\",10,err,\"m=1..5; standard H/CP/reversal and manuscript-derived recursion vs independent Fourier matrix\")\n\nerr=0; cases=0; min_nearest=1\nfor m in range(2,9):\n    N=1<<m; F=qft(m)\n    for theta in [0.,.125,.5,.999,1/3,np.sqrt(2)%1]:\n        wave=np.exp(2j*np.pi*np.arange(N)*theta)/np.sqrt(N)\n        p=np.abs(F.conj().T@wave)**2\n        nearest=round(N*theta)%N\n        min_nearest=min(min_nearest,p[nearest])\n        expect=[]\n        for y in range(N):\n            delta=theta-y/N\n            amp=np.mean(np.exp(2j*np.pi*np.arange(N)*delta))\n            expect.append(abs(amp)**2)\n        err=max(err,abs(p.sum()-1),np.max(np.abs(p-expect)));cases+=1\nassert min_nearest >= 4/np.pi**2 - TOL\nrecord(\"QPE distribution\",cases,err,f\"m=2..8; exact and nonexact phases, wrap-around; minimum nearest-cell probability {min_nearest:.12f}\")\n\nerr=0; cases=0\nfor N,a in [(7,3),(15,2)]:\n    d=1 << math.ceil(math.log2(N)); U=np.zeros((d,d),complex)\n    for x in range(d): U[(a*x)%N if x<N else x,x]=1\n    orbit=[1]; x=a%N\n    while x!=1: orbit.append(x);x=(a*x)%N\n    r=len(orbit); eigen=[]\n    for j in range(r):\n        psi=np.zeros(d,complex)\n        for k,x in enumerate(orbit):psi[x]=np.exp(-2j*np.pi*j*k/r)/np.sqrt(r)\n        err=max(err,np.max(np.abs(U@psi-np.exp(2j*np.pi*j/r)*psi)));eigen.append(psi);cases+=1\n    one=np.zeros(d);one[1]=1\n    err=max(err,np.max(np.abs(sum(eigen)/np.sqrt(r)-one)),np.max(np.abs(U.conj().T@U-np.eye(d))))\nrecord(\"Modular multiplication eigenstates\",cases,err,\"(N,a)=(7,3),(15,2); unitary extension fixes x>=N; negative eigenstate phase and positive eigenvalue\")\n\nerr=0; cases=0\nfor n in range(1,8):\n    N=1<<n; u=np.ones(N)/np.sqrt(N)\n    for s in range(1,N):\n        theta=np.arcsin(np.sqrt(s/N)); state=u.copy()\n        for t in range(min(12,math.floor(np.pi/(4*theta))+3)):\n            expect=np.sin((2*t+1)*theta)**2\n            err=max(err,abs(np.sum(state[:s]**2)-expect),abs(state@state-1));cases+=1\n            state[:s]*=-1\n            state=2*state.mean()-state\n        tstar=math.floor(np.pi/(4*theta)) if s<=N/2 else 0\n        p=np.sin((2*tstar+1)*theta)**2\n        assert p >= max(1-s/N,s/N)-TOL\nrecord(\"Grover amplitudes / integer iteration policy\",cases,err,\"n=1..7; all nontrivial solution counts; vector reflections compared to analytic rotation\")\n\ncases=0\nfor a in range(2):\n    for b in range(2):\n        for c in range(2):\n            assert c^((a^1)&(b^1))^1 == c^(a|b)\n            s=a^b^c; carry=(a&b)|((a^b)&c)\n            assert a+b+c == s+2*carry\n            cases+=1\nrecord(\"OR and full-adder truth tables\",cases,0,\"all binary inputs; general target c in OR embedding\")\n\nparser=argparse.ArgumentParser(description=__doc__)\nparser.add_argument('--output',type=Path,default=ROOT/'build'/'validation.json')\nargs=parser.parse_args()\nout=args.output\nout.parent.mkdir(parents=True,exist_ok=True)\nout.write_text(json.dumps({\"kind\":\"independent NumPy checks\",\"tolerance\":TOL,\"checks\":checks},ensure_ascii=False,indent=2),encoding='utf-8')\nprint(json.dumps({\"checks\":len(checks),\"cases\":sum(x['cases'] for x in checks),\"max_error\":max(x['max_error'] for x in checks),\"result\":str(out)},ensure_ascii=True))\n"};
